"""Creative mode: a printed part declared `source: meshy` gets an organic / cosmetic shell generated by Meshy and is
fused with its exact mechanical features into ONE printable body.

project.yaml:
    parts:
      shell:
        file: parts/shell.py          # build(ctx): the exact features (bosses, flanges, joints, fastener sites)
        source: meshy
        prompt: "a dragon-scale knuckle cover, smooth inside"   # what to ask Meshy for (text-to-3D)
        mesh: meshes/shell.glb        # the generated model, cached in the project (default meshes/<part>.<glb|stl|obj>)
        bounds: [[x0, y0, z0], [x1, y1, z1]]   # where the shell goes, part frame; the mesh is scaled to fill it
        fit: stretch | uniform        # stretch each axis to the bounds (default) or keep proportions, centred

The part file builds its features as usual and registers what must be cut through the shell with
`ctx.mesh_cut(solid)` (holes, pockets, keep-outs): the merged body = (shell U features) - cuts. The booleans run in
mesh space with manifold3d (0.2-1.6 s for 80k-330k triangles, prototype docs/prototypes/mesh_merge.py), not through
the B-rep kernel. A broken download is repaired per connected piece (merge vertices + fill holes, else voxel remesh)
and the pieces are unioned, so a stray overlapping fragment cannot leave a second body.

The item keeps its B-rep (the features) for joints, fastener/pin sites, FEA and STEP; the merged mesh rides along as
`shape.kerf_mesh = (V, F)` in the part frame and is what kerf/geom uses for print checks, interference, bounding box,
volume, the STL/3MF/plate exports and the renders.

Generating the mesh is not something the engine can do (Meshy is reached through its MCP tools). When the file is
missing, the build reports the exact prompt and path; the `kerf` skill then runs Meshy text-to-3D, downloads the
model into that path and records the task in meshes/<part>.meshy.json.
"""
from __future__ import annotations

import time
from pathlib import Path

import numpy as np

EXTS = (".glb", ".gltf", ".stl", ".obj", ".ply", ".3mf")
VOXEL_PITCH_FRAC = 1 / 250      # voxel remesh pitch as a fraction of the shell's largest bound
SLIVER_MM = 0.01                # merged mesh is simplified at 10 um (a printer resolves ~0.1 mm)


class MeshyError(ValueError):
    pass


def mesh_path(proj_dir: Path, pid: str, spec: dict) -> Path:
    if spec.get("mesh"):
        return proj_dir / spec["mesh"]
    for e in EXTS:
        p = proj_dir / "meshes" / f"{pid}{e}"
        if p.exists():
            return p
    return proj_dir / "meshes" / f"{pid}.glb"


def load(path: Path):
    import trimesh
    m = trimesh.load(str(path), force="mesh", process=False)
    if not isinstance(m, trimesh.Trimesh) or len(m.faces) == 0:
        raise MeshyError(f"{path.name} holds no triangles")
    return m


def fit_bounds(m, bounds, fit: str = "stretch"):
    """Scale + move the mesh so its bounding box fills `bounds` (part frame)."""
    lo, hi = np.asarray(bounds[0], float), np.asarray(bounds[1], float)
    if np.any(hi - lo <= 0):
        raise MeshyError(f"bounds {bounds} must be [[x0,y0,z0],[x1,y1,z1]] with x1 > x0 etc.")
    m = m.copy()
    mlo, mhi = m.bounds
    size = np.maximum(mhi - mlo, 1e-9)
    s = (hi - lo) / size
    if fit == "uniform":
        s = np.full(3, float(np.min(s)))
    elif fit != "stretch":
        raise MeshyError(f"fit must be 'stretch' or 'uniform', not '{fit}'")
    v = (m.vertices - (mlo + mhi) / 2) * s + (lo + hi) / 2
    m.vertices = v
    return m


def to_manifold(m):
    import manifold3d as mf
    return mf.Manifold(mf.Mesh(vert_properties=np.asarray(m.vertices, np.float32), tri_verts=np.asarray(m.faces, np.uint32)))


def from_manifold(M):
    import trimesh
    mm = M.to_mesh()
    return trimesh.Trimesh(np.asarray(mm.vert_properties[:, :3], float), np.asarray(mm.tri_verts, np.int64), process=False)


def _ok(M) -> bool:
    return M.status().name == "NoError" and not M.is_empty()


def repair(m, pitch: float):
    """Cheap first (merge vertices, drop degenerate faces, fill holes, fix normals); voxel remesh if still not a
    closed manifold (always closed, slightly smoothed at `pitch`)."""
    import trimesh
    m = m.copy()
    m.merge_vertices()
    m.update_faces(m.nondegenerate_faces())
    m.remove_unreferenced_vertices()
    trimesh.repair.fill_holes(m)
    trimesh.repair.fix_normals(m)
    if m.is_watertight:
        M = to_manifold(m)
        if _ok(M):
            return M, "fill_holes"
    v = m.voxelized(pitch=pitch).fill()
    r = v.marching_cubes
    r.apply_transform(v.transform)
    M = to_manifold(r)
    if not _ok(M):
        raise MeshyError(f"voxel remesh did not give a closed body ({M.status().name})")
    return M, "voxel_remesh"


def repair_union(m, pitch: float):
    """Repair every connected piece on its own, then union them (one body even if the download had junk pieces)."""
    import manifold3d as mf
    parts, how = [], set()
    m = m.copy()
    m.merge_vertices()          # STL/OBJ downloads repeat vertices per triangle; without this every face is a "piece"
    pieces = m.split(only_watertight=False) if len(m.faces) else []
    for c in pieces:
        if len(c.faces) < 4:
            continue
        M, h = repair(c, pitch)
        how.add(h)
        if M.volume() > 1e-3:
            parts.append(M)
    if not parts:
        raise MeshyError("the generated mesh has no closed piece with volume")
    return mf.Manifold.batch_boolean(parts, mf.OpType.Add), sorted(how)


def brep_manifold(shape, tol: float = 0.01, ang: float = 0.1):
    """Manifold of a build123d shape (its current location), tessellated fine so holes keep their size."""
    import trimesh
    verts, tris = shape.tessellate(tol, ang)
    v = np.array([[p.X, p.Y, p.Z] for p in verts], float)
    f = np.array(tris, np.int64).reshape(-1, 3)
    t = trimesh.Trimesh(v, f, process=True)          # merges the per-face vertex copies into one closed mesh
    M = to_manifold(t)
    if not _ok(M):
        trimesh.repair.fix_normals(t)
        M = to_manifold(t)
    if not _ok(M):
        raise MeshyError(f"could not turn a B-rep feature into a closed mesh ({M.status().name})")
    return M


def merge(shell_mesh, features, cuts, bounds, fit="stretch"):
    """(fitted + repaired shell U features) - cuts. Returns (trimesh, info)."""
    import manifold3d as mf
    t0 = time.time()
    fitted = fit_bounds(shell_mesh, bounds, fit)
    pitch = float(np.max(np.asarray(bounds[1], float) - np.asarray(bounds[0], float))) * VOXEL_PITCH_FRAC
    S, how = repair_union(fitted, pitch)
    out = S
    if features is not None:
        out = out + brep_manifold(features)
    if cuts:
        out = out - mf.Manifold.batch_boolean([brep_manifold(c) for c in cuts], mf.OpType.Add)
    # boolean slivers would otherwise fall apart under a 1e-4 mm vertex weld; simplify only collapses them on a
    # manifold rebuilt from plain vertices + triangles (not on the boolean result itself), hence the round trip
    out = to_manifold(from_manifold(out)).simplify(SLIVER_MM)
    if not _ok(out):
        raise MeshyError(f"merge failed ({out.status().name})")
    tm = from_manifold(out)
    bodies = len(tm.split(only_watertight=False))
    return tm, {"repair": how, "bodies": bodies, "triangles": int(len(tm.faces)), "watertight": bool(tm.is_watertight),
                "volume_mm3": round(float(out.volume()), 1), "seconds": round(time.time() - t0, 2)}


def apply(item, proj_dir: Path):
    """Called by project.build after a `source: meshy` part's build(): attach the merged mesh to item.shape."""
    spec = item.spec
    if not spec.get("prompt"):
        raise MeshyError(f"{item.id}: source: meshy needs a `prompt` (what to ask Meshy for)")
    if "bounds" not in spec:
        raise MeshyError(f"{item.id}: source: meshy needs `bounds: [[x0,y0,z0],[x1,y1,z1]]` (part frame)")
    p = mesh_path(proj_dir, item.id, spec)
    if not p.exists():
        raise MeshyError(f"{item.id}: Meshy model {p.relative_to(proj_dir)} is missing - generate it with Meshy "
                         f"text-to-3D (prompt: {spec['prompt']!r}), download it to {p.relative_to(proj_dir)} and "
                         f"record the task in meshes/{item.id}.meshy.json, then rebuild")
    shape = item.shape
    # features and cuts are already in the part frame (a solid's own location IS its placement: never reset it)
    cuts = list(getattr(shape, "kerf_mesh_cuts", []))
    tm, info = merge(load(p), shape, cuts, spec["bounds"], spec.get("fit", "stretch"))
    if info["bodies"] != 1:
        raise MeshyError(f"{item.id}: shell and features merged into {info['bodies']} separate bodies; make the "
                         f"features reach into the shell (or the bounds overlap the features)")
    # store relative to the shape's base geometry, so world = shape.location x V, exactly like the B-rep
    t = shape.location.wrapped.Transformation()
    L = np.array([[t.Value(r + 1, c + 1) for c in range(4)] for r in range(3)])
    R, o = L[:, :3], L[:, 3]
    V = (np.asarray(tm.vertices, float) - o) @ R          # R orthonormal: inverse = transpose
    shape.kerf_mesh = (V, np.asarray(tm.faces, np.int64))
    info["mesh"] = str(p.relative_to(proj_dir))
    shape.kerf_mesh_info = info
    return info
